"use client";

import { createContext, useCallback, useContext, useMemo, useRef, useState, type ReactNode } from "react";

export type TicketStatus = "resolved" | "escalated" | "processing";

export type Ticket = {
  id: string;
  message: string;
  status: TicketStatus;
  statusLabel: string;
  actions: string[];
  time: string;
  sku: string;
};

export type InventoryItem = {
  sku: string;
  name: string;
  size: number;
  stock: number;
  res: number;
  wh: string;
};

export const MOCK_TICKET = {
  message: "Jordan 4 size 43 exchange",
  status: "resolved" as TicketStatus,
  statusLabel: "Resolved Autonomously",
  actions: ["RESERVE_STOCK", "CREATE_LABEL"],
  time: "Just now",
  sku: "AJ4-MIL-43",
};

const createInitialTickets = (): Ticket[] => [
  {
    id: "TCK-9042",
    message: "Jordan 4s are too tight, need size 43.",
    status: "resolved",
    statusLabel: "Resolved Autonomously",
    actions: ["RESERVE_STOCK", "CREATE_LABEL"],
    time: "Just now",
    sku: "AJ4-MIL-43",
  },
  {
    id: "TCK-9043",
    message: "I want a refund but I bought these 90 days ago.",
    status: "escalated",
    statusLabel: "Escalated to Human",
    actions: ["POLICY_DENY"],
    time: "2 min ago",
    sku: "SMB-OG-41",
  },
  {
    id: "TCK-9044",
    message: "Need a size 10 exchange.",
    status: "resolved",
    statusLabel: "Resolved (Recovered)",
    actions: ["API_TIMEOUT_RECOVERED"],
    time: "5 min ago",
    sku: "GK30-BLK-44",
  },
];

const createInitialInventory = (): InventoryItem[] => [
  { sku: "AJ4-MIL-43", name: "Air Jordan 4 Military", size: 43, stock: 5, res: 1, wh: "WH-AMS-02" },
  { sku: "AJ4-MIL-42", name: "Air Jordan 4 Military", size: 42, stock: 3, res: 0, wh: "WH-AMS-02" },
  { sku: "SMB-OG-41", name: "Adidas Samba OG", size: 41, stock: 12, res: 2, wh: "WH-BER-01" },
  { sku: "NB550-GRY-39", name: "New Balance 550 Grey", size: 39, stock: 0, res: 0, wh: "WH-BER-01" },
  { sku: "GK30-BLK-44", name: "Asics Gel-Kayano 30", size: 44, stock: 5, res: 1, wh: "WH-AMS-02" },
];

type SwapDeskContextValue = {
  tickets: Ticket[];
  inventory: InventoryItem[];
  simulateTicket: () => Ticket;
  submitCustomerTicket: (message: string) => Ticket;
  resetMockData: () => void;
  getTicket: (id: string) => Ticket | undefined;
};

const SwapDeskContext = createContext<SwapDeskContextValue | null>(null);

export function SwapDeskProvider({ children }: { children: ReactNode }) {
  const [tickets, setTickets] = useState<Ticket[]>(createInitialTickets);
  const [inventory, setInventory] = useState<InventoryItem[]>(createInitialInventory);
  const seq = useRef(9045);

  const simulateTicket = useCallback(() => {
    const ticket: Ticket = { id: `TCK-${seq.current++}`, ...MOCK_TICKET };
    setTickets((prev) => [ticket, ...prev]);
    setInventory((prev) =>
      prev.map((item) =>
        item.sku === MOCK_TICKET.sku
          ? { ...item, stock: Math.max(0, item.stock - 1), res: item.res + 1 }
          : item,
      ),
    );
    return ticket;
  }, []);

  const submitCustomerTicket = useCallback((message: string) => {
    const text = message.trim() || "My Jordan 4s arrived but are too tight. I need to exchange for a size 43.";
    const ticket: Ticket = {
      id: `TCK-${seq.current++}`,
      message: text,
      status: "processing",
      statusLabel: "Agent Processing",
      actions: ["INTAKE", "ROUTING"],
      time: "Just now",
      sku: "AJ4-MIL-43",
    };
    setTickets((prev) => [ticket, ...prev]);
    return ticket;
  }, []);

  const resetMockData = useCallback(() => {
    setTickets([]);
    setInventory(createInitialInventory());
  }, []);

  const getTicket = useCallback((id: string) => tickets.find((ticket) => ticket.id === id), [tickets]);

  const value = useMemo(
    () => ({ tickets, inventory, simulateTicket, submitCustomerTicket, resetMockData, getTicket }),
    [tickets, inventory, simulateTicket, submitCustomerTicket, resetMockData, getTicket],
  );

  return <SwapDeskContext.Provider value={value}>{children}</SwapDeskContext.Provider>;
}

export function useSwapDesk() {
  const context = useContext(SwapDeskContext);
  if (!context) {
    throw new Error("useSwapDesk must be used within a SwapDeskProvider");
  }
  return context;
}

"""Serving layer for the frontend demo: deterministic cases over SQLite.

No model, no queue. Requests execute synchronously (millisecond SQLite
transactions), so status reads are never blocked. Business rules stay in
operations.py; this module only sequences them with the documented demo
policy. Cases accumulate in one shared database; a restart reuses every
existing identity instead of reseeding.
"""

from __future__ import annotations

import contextlib
import json
import os
import sqlite3
import uuid
from datetime import date
from pathlib import Path

from . import faults as _faults
from .agent.graph import AgentContext, derive_outcome
from .agent.prompts import render_reply
from . import telemetry as _telemetry
from .db import connect, init_db
from .fixtures import load_fixtures
from .models import OrderItem
from .operations import (
    InsufficientStockError,
    LabelTimeoutError,
    OperationError,
    TransientError,
    WorkerCrashedError,
    create_label,
    create_return,
    escalate_case,
    finalize_arranged,
    find_exchange_stock,
    get_case,
    note_case,
    reserve_replacement,
)
from .policy import check_eligibility

MAX_ATTEMPTS = 3


def default_db_path() -> Path:
    return Path(os.environ.get("SWAPDESK_DB", "swapdesk.db"))


def ensure_db(db_path: str | Path) -> None:
    """Create schema; seed fixtures only on a fresh database."""
    conn = connect(db_path)
    try:
        init_db(conn)
        empty = conn.execute(
            "SELECT COUNT(*) AS n FROM orders").fetchone()["n"] == 0
        if empty:
            load_fixtures(conn)
    finally:
        conn.close()


def _item_record(row: sqlite3.Row) -> OrderItem:
    return OrderItem(
        id=row["id"], order_id=row["order_id"], sku=row["sku"],
        size=row["size"], qty=row["qty"], price_cents=row["price_cents"],
        status=row["status"], delivered_at=row["delivered_at"],
        final_sale=bool(row["final_sale"]), created_at=row["created_at"])


def _fetch_item(db_path, order_item_id: str):
    conn = connect(db_path)
    try:
        return conn.execute("SELECT * FROM order_items WHERE id = ?",
                            (order_item_id,)).fetchone()
    finally:
        conn.close()


def _pool(db_path, sku: str, size: str):
    conn = connect(db_path)
    try:
        return find_exchange_stock(conn, sku, size)
    finally:
        conn.close()


def _next_run_id(db_path, case_id: str) -> str:
    conn = connect(db_path)
    try:
        rows = conn.execute(
            "SELECT DISTINCT run_id FROM operations WHERE case_id = ?",
            (case_id,)).fetchall()
    finally:
        conn.close()
    taken = {r["run_id"] for r in rows}
    n = 1
    while f"RUN-{n}" in taken:
        n += 1
    return f"RUN-{n}"


class _Exhausted(Exception):
    pass


def _attempt(log_attempts: dict, step: str, fn):
    last = None
    for n in range(1, MAX_ATTEMPTS + 1):
        log_attempts[step] = n
        try:
            return fn()
        except (TransientError, WorkerCrashedError, LabelTimeoutError,
                InsufficientStockError) as exc:
            last = exc
    raise _Exhausted(str(last))


def _escalate_none(db_path, case_id: str, reason: str) -> dict:
    note_case(db_path, case_id=case_id, state="escalated", detail=reason)
    return {"outcome": "escalation", "exchange_id": None,
            "reason": f"escalated: {reason}"}


def _escalate_held(db_path, case_id: str, run_id: str, exchange_id: str,
                   reason: str, log_attempts: dict) -> dict:
    key = f"{case_id}:{run_id}:escalate"
    last = None
    for n in range(1, MAX_ATTEMPTS + 1):
        log_attempts["escalate"] = n
        try:
            out = escalate_case(db_path, case_id=case_id, run_id=run_id,
                                op_key=key, exchange_id=exchange_id,
                                reason=reason)
            return {"outcome": "escalation",
                    "exchange_id": exchange_id,
                    "reason": f"escalated: {reason}",
                    "status": out.status}
        except (TransientError, OperationError) as exc:
            last = exc
    return {"outcome": "escalation", "exchange_id": exchange_id,
            "reason": f"escalated: {reason} (cleanup pending: {last})",
            "status": "cleanup_pending"}


def _run_flow(db_path, *, case_id: str, run_id: str, order_id: str,
              order_item_id: str, requested_size: str, qty: int,
              consent_size: str | None) -> dict:
    """Execute one run of the demo policy. Returns outcome fields."""
    log_attempts: dict = {}
    row = _fetch_item(db_path, order_item_id)
    if row is None or row["order_id"] != order_id:
        note_case(db_path, case_id=case_id, state="needs_information",
                  detail="provide your order number and item id")
        return {"outcome": "clarification", "exchange_id": None,
                "question": "provide your order number and item id",
                "attempts": log_attempts}
    item = _item_record(row)
    eligible, reason = check_eligibility(item, date.today())
    if not eligible:
        note_case(db_path, case_id=case_id, state="denied", detail=reason)
        return {"outcome": "denial", "exchange_id": None,
                "reason": f"denied: {reason}", "attempts": log_attempts}
    size = (requested_size or "").strip()
    if not size:
        note_case(db_path, case_id=case_id, state="needs_information",
                  detail="which size do you need?")
        return {"outcome": "clarification", "exchange_id": None,
                "question": "which size do you need?",
                "attempts": log_attempts}
    pool = _pool(db_path, item.sku, size)
    available = pool.available if pool else 0
    authorized = size
    if available < qty:
        consent = consent_size
        if consent:
            alt = _pool(db_path, item.sku, consent)
            if alt is not None and alt.available >= qty:
                authorized = consent
                note_case(db_path, case_id=case_id, state="received",
                          detail=f"consent:{consent}")
        if authorized == size:
            note_case(db_path, case_id=case_id, state="needs_information",
                      detail=f"size {size} unavailable")
            return {
                "outcome": "clarification", "exchange_id": None,
                "question": f"size {size} is unavailable "
                            f"(only {available} unit(s) in stock); reply "
                            "with an alternative size or ask for a human",
                "attempts": log_attempts}

    def _key(step: str) -> str:
        return f"{case_id}:{run_id}:{step}"

    try:
        res = _attempt(log_attempts, "reserve", lambda: reserve_replacement(
            db_path, case_id=case_id, run_id=run_id,
            op_key=_key("reserve"), order_id=order_id,
            order_item_id=order_item_id, size=authorized, qty=qty,
            requested_size=size, consent=authorized != size))
    except _Exhausted as exc:
        return {**_escalate_none(
            db_path, case_id, f"reservation kept failing: {exc}"),
            "attempts": log_attempts}
    except OperationError as exc:
        return {**_escalate_none(db_path, case_id, f"reservation failed: {exc}"),
                "attempts": log_attempts}
    if res.duplicate and res.status == "arranged":
        return {"outcome": "arranged", "exchange_id": res.exchange_id,
                "duplicate": True, "attempts": log_attempts}
    exchange_id = res.exchange_id

    def _do_return():
        return create_return(db_path, case_id=case_id, run_id=run_id,
                             op_key=_key("return"), exchange_id=exchange_id)

    def _do_label():
        return create_label(db_path, case_id=case_id, run_id=run_id,
                            op_key=_key("label"), exchange_id=exchange_id)

    def _do_finalize():
        return finalize_arranged(
            db_path, case_id=case_id, run_id=run_id,
            op_key=_key("finalize"), exchange_id=exchange_id)

    try:
        _attempt(log_attempts, "return", _do_return)
        _attempt(log_attempts, "label", _do_label)
        _attempt(log_attempts, "finalize", _do_finalize)
    except _Exhausted as exc:
        return {**_escalate_held(db_path, case_id, run_id, exchange_id,
                                 f"flow kept failing: {exc}", log_attempts),
                "attempts": log_attempts}
    except OperationError as exc:
        return {**_escalate_held(db_path, case_id, run_id, exchange_id,
                                 f"flow failed: {exc}", log_attempts),
                "attempts": log_attempts}
    return {"outcome": "arranged", "exchange_id": exchange_id,
            "duplicate": res.duplicate, "attempts": log_attempts}


def _telemetry_span(case_id: str, run_id: str):
    import neatlogs

    @contextlib.contextmanager
    def _span():
        with neatlogs.trace(f"swapdesk-api:{case_id}",
                             kind="WORKFLOW") as span:
            span.set_attribute("swapdesk.case_id", case_id)
            span.set_attribute("swapdesk.run_id", run_id)
            yield span

    return _span()


def _verified_reply(db_path, case_id: str) -> dict:
    ctx = AgentContext(db_path=db_path, case_id=case_id, run_id="",
                       message="")
    decided = derive_outcome(ctx)
    return {"outcome": decided["outcome"],
            "exchange_id": decided["exchange_id"],
            "reply": render_reply(decided["outcome"], decided["data"])}


def submit_ticket(db_path, *, order_id: str, order_item_id: str,
                  size: str, qty: int = 1, message: str = "",
                  consent_size: str | None = None,
                  case_id: str | None = None) -> dict:
    """Open a case and run it to a verified outcome."""
    ensure_db(db_path)
    cid = case_id or f"CASE-{uuid.uuid4().hex[:8]}"
    if get_case(db_path, cid) is not None:
        raise ValueError(f"case {cid!r} already exists")
    _telemetry.init_telemetry()
    with _telemetry_span(cid, "RUN-1"):
        result = _run_flow(db_path, case_id=cid, run_id="RUN-1",
                           order_id=order_id, order_item_id=order_item_id,
                           requested_size=size, qty=qty,
                           consent_size=consent_size)
    verified = _verified_reply(db_path, cid)
    return {"case_id": cid, "run_id": "RUN-1", **verified,
            "attempts": result.get("attempts", {})}


def continue_case(db_path, *, case_id: str, message: str = "",
                  consent_size: str | None = None,
                  order_id: str | None = None,
                  order_item_id: str | None = None,
                  size: str | None = None, qty: int = 1) -> dict:
    """Continue a case with new customer input.

    Terminal cases report their verified status unchanged. Otherwise the
    request runs again under a fresh run id (duplicate-safe). The request
    comes from explicit fields when given, else from the case's latest
    exchange row; without either, continuation is a client error.
    """
    ensure_db(db_path)
    current = _verified_reply(db_path, case_id)
    if current["outcome"] in ("arranged", "denial"):
        return {"case_id": case_id, "run_id": None, **current,
                "attempts": {}, "continued": False}
    run_id = _next_run_id(db_path, case_id)
    if order_id is not None and order_item_id is not None and size is not None:
        request = {"order_id": order_id, "order_item_id": order_item_id,
                   "requested_size": size, "qty": qty}
    else:
        conn = connect(db_path)
        try:
            anchor = conn.execute(
                "SELECT order_id, order_item_id, requested_size, qty "
                "FROM exchanges WHERE case_id = ? "
                "ORDER BY rowid DESC LIMIT 1", (case_id,)).fetchone()
        finally:
            conn.close()
        if anchor is None:
            raise ValueError(
                f"case {case_id!r} has no recorded request to continue; "
                "provide order_id, order_item_id and size")
        request = dict(anchor)
    _ = message
    _telemetry.init_telemetry()
    with _telemetry_span(case_id, run_id):
        result = _run_flow(db_path, case_id=case_id, run_id=run_id,
                           consent_size=consent_size, **request)
    verified = _verified_reply(db_path, case_id)
    return {"case_id": case_id, "run_id": run_id, **verified,
            "attempts": result.get("attempts", {}), "continued": True}


def case_status(db_path, case_id: str) -> dict | None:
    """Verified status of a case, or None when unknown."""
    ensure_db(db_path)
    if get_case(db_path, case_id) is None:
        return None
    conn = connect(db_path)
    try:
        runs = [r["run_id"] for r in conn.execute(
            "SELECT DISTINCT run_id FROM operations WHERE case_id = ?",
            (case_id,))]
    finally:
        conn.close()
    return {"case_id": case_id, **_verified_reply(db_path, case_id),
            "runs": sorted(runs)}


def case_timeline(db_path, case_id: str) -> list[dict] | None:
    """Sanitized run/action timeline: journal plus operation records."""
    ensure_db(db_path)
    if get_case(db_path, case_id) is None:
        return None
    conn = connect(db_path)
    try:
        ops = {r["idempotency_key"]: dict(r) for r in conn.execute(
            "SELECT * FROM operations WHERE case_id = ? ORDER BY rowid",
            (case_id,))}
        events = []
        for row in conn.execute(
                "SELECT * FROM journal WHERE op_key IN "
                "(SELECT idempotency_key FROM operations WHERE case_id = ?) "
                "ORDER BY rowid", (case_id,)):
            op = ops.get(row["op_key"], {})
            events.append({
                "op_key": row["op_key"],
                "op_type": op.get("op_type"),
                "event": row["event"],
                "status": op.get("status"),
                "result": (json.loads(op["result_json"])
                           if op.get("result_json") else None),
                "created_at": row["created_at"],
            })
    finally:
        conn.close()
    return events


def fixture_catalog(db_path) -> dict:
    """Synthetic fixture choices for frontend dropdowns, plus policy."""
    from .operations import get_return_policy

    ensure_db(db_path)
    conn = connect(db_path)
    try:
        orders = []
        for order in conn.execute("SELECT * FROM orders ORDER BY id"):
            items = [dict(r) for r in conn.execute(
                "SELECT id, sku, size, qty, status, delivered_at, "
                "final_sale FROM order_items WHERE order_id = ? ORDER BY id",
                (order["id"],))]
            orders.append({"id": order["id"],
                           "customer_ref": order["customer_ref"],
                           "items": items})
    finally:
        conn.close()
    return {"orders": orders, "policy": get_return_policy()}


def arm_demo_fault(*, case_id: str, run_id: str, step: str, point: str,
                   times: int = 1) -> dict:
    """Demo-only failure control: arm a fault on one operation key."""
    _faults.inject(f"{case_id}:{run_id}:{step}", point, times)
    return {"armed": True, "op_key": f"{case_id}:{run_id}:{step}",
            "point": point, "times": times}


def clear_demo_faults() -> dict:
    """Demo-only failure control: disarm every fault."""
    _faults.clear()
    return {"cleared": True}

"""Studio's inspectable agent subgraph, isolated cases, offline-first runs.

The compiled production agent is registered directly as the `agent` node.
Middleware binds its model and tools to the prepared case without recompiling
or hiding the model/tools loop. Shared message state is checkpointed by the
parent/serving platform. No model client is constructed at graph import.
"""
from __future__ import annotations

import json
import os
import re
from pathlib import Path
from uuid import uuid4

from langchain.agents import AgentState
from langchain.agents.middleware import AgentMiddleware
from langchain.agents.middleware.types import ExtendedModelResponse, ModelResponse
from langchain_core.messages import AIMessage, RemoveMessage
from langgraph.graph import END, StateGraph
from langgraph.graph.message import REMOVE_ALL_MESSAGES
from langgraph.types import Command

from .. import faults, telemetry
from ..db import connect, init_db
from ..fixtures import load_fixtures
from ..operations import get_case
from .capped import BudgetExceeded, BudgetedChatModel
from .graph import AgentContext, ConfigurationError, build_agent, derive_outcome, compose_input
from .prompts import render_reply
from .scripted import SCENARIOS, WIRING_LABEL, ScriptedChatModel, script_for
from .tools import ToolContext, build_tools

STUDIO_ROOT = Path("studio_data")


class StudioState(AgentState, total=False):
    mode: str
    scenario: str
    message: str
    case_id: str
    run_id: str
    resume: bool
    budget: int | None
    consent_size: str | None
    db_path: str
    outcome: str | None
    reply: str | None
    exchange_id: str | None
    evidence: dict
    agent_trace: list
    error: str | None
    script_cursor: int
    requests_spent: int
    generated_case_id: str | None
    generated_run_id: str | None


def _studio_root() -> Path:
    return Path(os.environ.get("SWAPDESK_STUDIO_ROOT") or STUDIO_ROOT).resolve()


def default_case_id(scenario: str) -> str:
    return f"DEMO-{scenario.upper()}-{uuid4().hex[:12]}"


def _identity(value, label):
    if not isinstance(value, str) or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_-]{0,95}", value):
        raise ValueError(f"{label} must use 1–96 letters, digits, underscores or hyphens")
    return value


def _case_db(case_id: str) -> Path:
    root = _studio_root()
    candidate = (root / _identity(case_id, "case_id") / "shop.db").resolve()
    if not candidate.is_relative_to(root):
        raise ValueError("case path escapes the Studio data directory")
    return candidate


def _ctx_from(state) -> AgentContext:
    return AgentContext(db_path=state["db_path"], case_id=state["case_id"],
                        run_id=state["run_id"], message=state["message"],
                        consent_size=state.get("consent_size"))


def _require_live_config() -> str:
    telemetry.load_dotenv()
    model_id = os.environ.get("SWAPDESK_MODEL")
    if not model_id:
        raise ConfigurationError("live mode needs SWAPDESK_MODEL; no model calls made")
    if not os.environ.get("GEMINI_API_KEY"):
        raise ConfigurationError("live mode needs GEMINI_API_KEY; no model calls made")
    return model_id


def _cleared():
    return {"outcome": None, "reply": None, "exchange_id": None,
            "evidence": {}, "agent_trace": [], "error": None}


def prepare(state: StudioState) -> dict:
    """Initialize a fresh synthetic case or explicitly continue its identity."""
    cleared = _cleared()
    try:
        mode = state.get("mode") or "offline"
        scenario = state.get("scenario") or "arrange"
        if scenario not in SCENARIOS:
            raise ValueError(f"unknown scenario; choose {sorted(SCENARIOS)}")
        resume = state.get("resume", False)
        if type(resume) is not bool:
            raise ValueError("resume must be true or false")
        if resume and (not state.get("case_id") or not state.get("run_id")):
            raise ValueError("resume requires the original case_id and run_id")
        requested_case = state.get("case_id")
        requested_run = state.get("run_id")
        if not resume and requested_case == state.get("generated_case_id"):
            requested_case = None
        if not resume and requested_run == state.get("generated_run_id"):
            requested_run = None
        case_id = _identity(requested_case or default_case_id(scenario), "case_id")
        run_id = _identity(requested_run or f"RUN-{uuid4().hex[:12]}", "run_id")
        budget = state.get("budget")
        if mode == "live":
            if type(budget) is not int or budget < 1:
                raise ValueError("live mode needs an explicit positive integer budget; no model calls made")
            _require_live_config()  # before touching the demo database
        db_path = _case_db(case_id)
        manifest = db_path.parent / "identity.json"
        exists = db_path.exists()
        if exists and not resume:
            raise ValueError("case is already active; use original case_id/run_id with resume=true or a new case_id; nothing was reset")
        if resume and not exists:
            raise ValueError("nothing to resume for this case")
        saved = {}
        if exists:
            if not manifest.exists():
                raise ValueError("case has no identity manifest; use a fresh case_id")
            saved = json.loads(manifest.read_text())
            if saved.get("run_id") != run_id or saved.get("scenario") != scenario or saved.get("mode") != mode:
                raise ValueError("resume must preserve the original run_id, scenario and mode")
        else:
            db_path.parent.mkdir(parents=True, exist_ok=False)
            conn = connect(db_path)
            try:
                init_db(conn)
                load_fixtures(conn)
            finally:
                conn.close()
            manifest.write_text(json.dumps({"run_id": run_id, "scenario": scenario, "mode": mode}))
            conn = connect(db_path)
            try:
                conn.execute("CREATE TABLE studio_request_budget (id INTEGER PRIMARY KEY, spent INTEGER NOT NULL)")
                conn.execute("INSERT INTO studio_request_budget VALUES (1, 0)")
                conn.commit()
            finally:
                conn.close()
        message = state.get("message") or SCENARIOS[scenario]["message"]
        update = {**cleared, "mode": mode, "scenario": scenario,
                  "case_id": case_id, "run_id": run_id, "resume": resume,
                  "message": message, "budget": budget,
                  "consent_size": state.get("consent_size"), "db_path": str(db_path),
                  "requests_spent": _spent_on_disk({"case_id": case_id}),
                  "generated_case_id": case_id if not requested_case else None,
                  "generated_run_id": run_id if not requested_run else None}
        ctx = _ctx_from(update)
        if resume:
            if not state.get("messages"):
                raise ValueError("conversation resume requires the original Studio thread; use its saved state")
            # Do not add a new user message between pending AI calls and tool results.
            # Interrupted execution is resumed with graph.invoke(None, same config).
            update["messages"] = []
        else:
            update["script_cursor"] = 0
            update["messages"] = [RemoveMessage(id=REMOVE_ALL_MESSAGES),
                                  {"role": "user",
                                   "content": compose_input(
                                       message, case_id, run_id,
                                       state.get("consent_size"))}]
        return update
    except (ValueError, OSError) as exc:
        return {**cleared, "error": str(exc)}
    except ConfigurationError as exc:
        return {**cleared, "error": str(exc)}


def _trace_messages(result: dict) -> list:
    trace = []
    for msg in result.get("messages", []):
        row = {"role": type(msg).__name__, "content": msg.content}
        if isinstance(msg, AIMessage):
            row["calls"] = [(c["name"], c["args"]) for c in msg.tool_calls]
            row["role"] = "model"
        if type(msg).__name__ == "ToolMessage":
            row.update(role="tool", name=msg.name, tool_call_id=msg.tool_call_id)
        trace.append(row)
    return trace


def _tools_for(state):
    ctx = _ctx_from(state)
    return build_tools(ToolContext(ctx.db_path, ctx.case_id, ctx.run_id))


def _spent_on_disk(state, increment=0):
    """Atomically reserve budget before a generation, including failed attempts.

    SQLite serializes reservations for concurrent submissions of the same case.
    A resume's budget is a cumulative ceiling for its original case/run.
    """
    conn = connect(_case_db(state["case_id"]))
    try:
        conn.execute("BEGIN IMMEDIATE")
        spent = conn.execute("SELECT spent FROM studio_request_budget WHERE id = 1").fetchone()[0]
        if increment:
            if spent >= state["budget"]:
                raise BudgetExceeded(f"model budget exhausted ({spent}/{state['budget']} attempts)")
            conn.execute("UPDATE studio_request_budget SET spent = spent + ? WHERE id = 1", (increment,))
        conn.commit()
        return spent + increment
    finally:
        conn.close()


class StudioMiddleware(AgentMiddleware):
    """Runtime binding for the statically registered production agent."""
    state_schema = StudioState

    def wrap_model_call(self, request, handler):
        state = request.state
        updates = {}
        try:
            if state["mode"] == "offline":
                sequence = script_for(state["scenario"], state["case_id"], state["run_id"])
                cursor = state.get("script_cursor", 0)
                # Scripts exercise actual tools but do not interpret user intent.
                model = ScriptedChatModel(sequence[cursor:cursor+1])
                updates["script_cursor"] = cursor + 1
            else:
                model = BudgetedChatModel(model=_require_live_config()).set_budget(1)
                updates["requests_spent"] = _spent_on_disk(state, 1)
            response = handler(request.override(model=model, tools=_tools_for(state)))
            return ExtendedModelResponse(response, Command(update=updates))
        except (BudgetExceeded, ConfigurationError) as exc:
            error = str(exc)
        except Exception as exc:
            # Provider errors can contain credentials or endpoints. Expose only
            # a type, never raw exception text, in user-visible state.
            error = f"agent model failed ({type(exc).__name__}); inspect local diagnostics"
        if state.get("mode") == "live":
            updates["requests_spent"] = _spent_on_disk(state)
        updates.pop("script_cursor", None)
        updates["error"] = error
        return ExtendedModelResponse(ModelResponse([AIMessage(content="Run stopped; see error state.")]),
                                     Command(update=updates))

    async def awrap_model_call(self, request, handler):
        # Studio's live async requests use the SAME budget reservation path.
        # Select through the sync implementation with a captured request, then
        # await the handler without running provider work on the event loop.
        captured = []
        def capture(changed):
            captured.append(changed)
            return ModelResponse([])
        prepared = self.wrap_model_call(request, capture)
        if not captured:
            return prepared
        try:
            response = await handler(captured[0])
            return ExtendedModelResponse(response, prepared.command)
        except Exception as exc:
            update = dict(prepared.command.update)
            update.pop("script_cursor", None)
            update["error"] = f"agent model failed ({type(exc).__name__}); inspect local diagnostics"
            return ExtendedModelResponse(ModelResponse([AIMessage(content="Run stopped; see error state.")]), Command(update=update))

    def wrap_tool_call(self, request, handler):
        tools = {tool.name: tool for tool in _tools_for(request.state)}
        # Arm only this case's fault, once, at the first reservation. No global
        # clear() which would erase another concurrent offline case's fault.
        state = request.state
        if (state["mode"] == "offline" and state["scenario"] == "recover"
                and request.tool_call["name"] == "reserve_replacement"
                and not any(type(m).__name__ == "ToolMessage" and m.name == "reserve_replacement"
                            for m in state.get("messages", []))):
            faults.inject(f"{state['case_id']}:{state['run_id']}:reserve", "crash", 1)
        return handler(request.override(tool=tools[request.tool_call["name"]]))

    async def awrap_tool_call(self, request, handler):
        # The original tools are synchronous SQLite operations. Use exactly
        # the synchronous binding/error semantics on a worker thread.
        import asyncio
        return await asyncio.to_thread(self.wrap_tool_call, request,
                                       lambda changed: changed.tool.invoke(changed.tool_call))


def _evidence(state):
    ctx = _ctx_from(state)
    conn = connect(ctx.db_path)
    try:
        exchanges = [dict(r) for r in conn.execute("SELECT * FROM exchanges WHERE case_id = ?", (ctx.case_id,))]
        ops = [dict(r) for r in conn.execute("SELECT idempotency_key, op_type, status FROM operations WHERE case_id = ?", (ctx.case_id,))]
        case = get_case(ctx.db_path, ctx.case_id)
    finally:
        conn.close()
    return {"mode": state["mode"], "label": WIRING_LABEL if state["mode"] == "offline" else "live Gemini run",
            "exchanges": exchanges, "operations": ops,
            "case_state": case["state"] if case else None,
            "requests_spent": state.get("requests_spent", 0)}


def verify(state):
    case = get_case(state["db_path"], state["case_id"])
    if not case or case["state"] not in {"arranged", "denied", "needs_information", "escalated", "cleanup_pending"}:
        return {**error_terminal(state), "error": "agent stopped without a persisted terminal case; no customer reply generated"}
    decided = derive_outcome(_ctx_from(state))
    reply = render_reply(decided["outcome"], decided["data"])
    evidence = {**_evidence(state), **decided, "reply": reply}
    return {"outcome": decided["outcome"], "reply": reply,
            "exchange_id": decided["exchange_id"], "evidence": evidence,
            "agent_trace": _trace_messages(state)}


def error_terminal(state):
    update = {"outcome": None, "reply": None, "exchange_id": None,
              "evidence": {}, "agent_trace": _trace_messages(state)}
    if state.get("db_path") and state.get("case_id"):
        try:
            update["evidence"] = {**_evidence(state), "diagnostic_only": True}
        except (OSError, ValueError):
            pass
    return update


def _builder(mode, interrupt_after_tools=False):
    # Static tool signatures at compile time; middleware substitutes only
    # bindings at execution time. Placeholder model cannot call a provider.
    ctx = AgentContext("unused-studio-placeholder.db", "PLACEHOLDER", "PLACEHOLDER", "")
    agent = build_agent(ctx, model=ScriptedChatModel([]), middleware=[StudioMiddleware()],
                        state_schema=StudioState, telemetry_enabled=False,
                        interrupt_after=["tools"] if interrupt_after_tools else None)
    def initial(state):
        return prepare({**state, "mode": mode})
    graph = StateGraph(StudioState)
    graph.add_node("prepare", initial)
    graph.add_node("agent", agent)
    graph.add_node("verify", verify)
    graph.add_node("error", error_terminal)
    graph.set_entry_point("prepare")
    graph.add_conditional_edges("prepare", lambda s: "error" if s.get("error") else "agent", {"error": "error", "agent": "agent"})
    graph.add_conditional_edges("agent", lambda s: "error" if s.get("error") else "verify", {"error": "error", "verify": "verify"})
    graph.add_edge("verify", END)
    graph.add_edge("error", END)
    return graph


def build_offline_graph(checkpointer=None, *, interrupt_after_tools=False):
    return _builder("offline", interrupt_after_tools).compile(checkpointer=checkpointer)


def build_live_graph(checkpointer=None):
    return _builder("live").compile(checkpointer=checkpointer)

"""Agent-facing tools: thin, typed wrappers over operations.

One concern only: translating backend results (and backend errors) into
JSON the model can act on. All safety rules live in operations.py; these
wrappers add no policy of their own.

Key discipline is structural: each tool derives its idempotency key from
(case_id, run_id, tool, attempt). Retrying the same tool reuses the key
automatically. A fresh key needs an explicit attempt number, so the model
can never mint one by accident after an uncertain write.
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path

import neatlogs
from langchain_core.tools import tool

from .. import operations as _ops


@dataclass(frozen=True)
class ToolContext:
    db_path: str | Path
    case_id: str
    run_id: str


def _key(ctx: ToolContext, name: str, attempt: int = 1) -> str:
    base = f"{ctx.case_id}:{ctx.run_id}:{name}"
    return base if attempt <= 1 else f"{base}#a{attempt}"


def _ok(**fields) -> str:
    return json.dumps({"ok": True, **fields}, sort_keys=True)


def _err(error: str, *, retry_same_key: bool = False,
         op_key: str | None = None) -> str:
    payload = {"ok": False, "error": error, "retry_same_key": retry_same_key}
    if op_key is not None:
        payload["op_key"] = op_key
    return json.dumps(payload, sort_keys=True)


def build_tools(ctx: ToolContext) -> list:
    """Create the agent's tool list bound to one case run."""
    db = ctx.db_path
    case_id, run_id = ctx.case_id, ctx.run_id

    @tool
    @neatlogs.span(kind="TOOL", tool_name="get_order")
    def get_order(order_id: str) -> str:
        """Look up an order and its items. Returns null when unknown."""
        conn = _ops._db.connect(db)
        try:
            order = _ops.get_order(conn, order_id)
            if order is None:
                return _ok(order=None)
            items = [dict(r) for r in conn.execute(
                "SELECT * FROM order_items WHERE order_id = ?",
                (order_id,)).fetchall()]
        finally:
            conn.close()
        return _ok(order={"id": order.id,
                          "customer_ref": order.customer_ref},
                   items=[{k: i[k] for k in (
                       "id", "sku", "size", "qty", "status", "delivered_at",
                       "final_sale")} for i in items])

    @tool
    @neatlogs.span(kind="TOOL", tool_name="get_return_policy")
    def get_return_policy() -> str:
        """Read the shop's return policy window and exclusions."""
        return _ok(policy=_ops.get_return_policy())

    @tool
    @neatlogs.span(kind="TOOL", tool_name="find_exchange_stock")
    def find_exchange_stock(sku: str, size: str) -> str:
        """Check available units of a SKU/size pool."""
        conn = _ops._db.connect(db)
        try:
            level = _ops.find_exchange_stock(conn, sku, size)
        finally:
            conn.close()
        if level is None:
            return _ok(pool=None)
        return _ok(pool={"sku": sku, "size": size,
                         "on_hand": level.on_hand, "held": level.held,
                         "available": level.available})

    @tool
    @neatlogs.span(kind="TOOL", tool_name="get_active_exchange")
    def get_active_exchange(order_item_id: str) -> str:
        """Return the open exchange for an item, if any."""
        conn = _ops._db.connect(db)
        try:
            found = _ops.get_active_exchange(conn, order_item_id)
        finally:
            conn.close()
        if found is None:
            return _ok(exchange=None)
        return _ok(exchange={"id": found.id, "status": found.status,
                             "authorized_size": found.authorized_size})

    @tool
    @neatlogs.span(kind="TOOL", tool_name="get_operation_status")
    def get_operation_status(op_key: str) -> str:
        """Re-query a past operation by key. Null means unknown: never
        assume a fresh key is safe on an uncertain write."""
        status = _ops.get_operation_status(db, op_key)
        return _ok(operation=status)

    @tool
    @neatlogs.span(kind="TOOL", tool_name="verify_exchange")
    def verify_exchange(exchange_id: str) -> str:
        """Read-only recovery handoff for an exchange."""
        try:
            hand = _ops.verify_exchange(db, exchange_id)
        except _ops.ExchangeNotFoundError as exc:
            return _err(str(exc))
        return _ok(exchange_id=hand.exchange_id, case_id=hand.case_id,
                   status=hand.status, return_id=hand.return_id,
                   label_id=hand.label_id, tracking_ref=hand.tracking_ref,
                   hold_active=hand.hold_active,
                   pending_cleanup=hand.pending_cleanup,
                   consistent=hand.consistent,
                   suggested_next=hand.suggested_next)

    @tool
    @neatlogs.span(kind="TOOL", tool_name="reserve_replacement")
    def reserve_replacement(order_id: str, order_item_id: str, size: str,
                            qty: int = 1, requested_size: str | None = None,
                            consent: bool = False,
                            attempt: int = 1) -> str:
        """Hold one replacement unit of the exact size. Pass
        requested_size plus consent=true only when the customer
        explicitly accepted a different size."""
        key = _key(ctx, "reserve", attempt)
        try:
            res = _ops.reserve_replacement(
                db, case_id=case_id, run_id=run_id, op_key=key,
                order_id=order_id, order_item_id=order_item_id, size=size,
                qty=qty, requested_size=requested_size, consent=consent)
        except (_ops.TransientError, _ops.WorkerCrashedError) as exc:
            return _err(str(exc), retry_same_key=True, op_key=key)
        except _ops.OperationError as exc:
            return _err(str(exc), op_key=key)
        except _ops.ReservationError as exc:
            return _err(str(exc), op_key=key)
        return _ok(exchange_id=res.exchange_id, status=res.status,
                   duplicate=res.duplicate, op_key=key)

    @tool
    @neatlogs.span(kind="TOOL", tool_name="create_return")
    def create_return(exchange_id: str, attempt: int = 1) -> str:
        """Create the return record for a reserved exchange."""
        key = _key(ctx, "return", attempt)
        try:
            res = _ops.create_return(db, case_id=case_id, run_id=run_id,
                                     op_key=key, exchange_id=exchange_id)
        except (_ops.TransientError,) as exc:
            return _err(str(exc), retry_same_key=True, op_key=key)
        except _ops.OperationError as exc:
            return _err(str(exc), op_key=key)
        return _ok(exchange_id=res.exchange_id, return_id=res.return_id,
                   status=res.status, duplicate=res.duplicate, op_key=key)

    @tool
    @neatlogs.span(kind="TOOL", tool_name="create_label")
    def create_label(exchange_id: str, attempt: int = 1) -> str:
        """Create the mock shipping label for a returned exchange."""
        key = _key(ctx, "label", attempt)
        try:
            res = _ops.create_label(db, case_id=case_id, run_id=run_id,
                                    op_key=key, exchange_id=exchange_id)
        except (_ops.TransientError, _ops.LabelTimeoutError) as exc:
            return _err(str(exc), retry_same_key=True, op_key=key)
        except _ops.OperationError as exc:
            return _err(str(exc), op_key=key)
        return _ok(exchange_id=res.exchange_id, label_id=res.label_id,
                   tracking_ref=res.tracking_ref, status=res.status,
                   duplicate=res.duplicate, op_key=key)

    @tool
    @neatlogs.span(kind="TOOL", tool_name="finalize_arranged")
    def finalize_arranged(exchange_id: str, attempt: int = 1) -> str:
        """Verify return plus label plus hold, then mark arranged."""
        key = _key(ctx, "finalize", attempt)
        try:
            res = _ops.finalize_arranged(db, case_id=case_id, run_id=run_id,
                                         op_key=key, exchange_id=exchange_id)
        except (_ops.TransientError,) as exc:
            return _err(str(exc), retry_same_key=True, op_key=key)
        except _ops.OperationError as exc:
            return _err(str(exc), op_key=key)
        return _ok(exchange_id=res.exchange_id, status=res.status,
                   duplicate=res.duplicate, op_key=key)

    @tool
    @neatlogs.span(kind="TOOL", tool_name="escalate_to_human")
    def escalate_to_human(exchange_id: str, reason: str,
                          attempt: int = 1) -> str:
        """Hand the case to a human: releases held stock, keeps history."""
        key = _key(ctx, "escalate", attempt)
        try:
            res = _ops.escalate_case(db, case_id=case_id, run_id=run_id,
                                     op_key=key, exchange_id=exchange_id,
                                     reason=reason)
        except (_ops.TransientError, _ops.ReleaseFailedError) as exc:
            return _err(str(exc), retry_same_key=True, op_key=key)
        except _ops.OperationError as exc:
            return _err(str(exc), op_key=key)
        return _ok(exchange_id=res.exchange_id, status=res.status,
                   hold_released=res.hold_released,
                   duplicate=res.duplicate, op_key=key)

    @tool
    @neatlogs.span(kind="TOOL", tool_name="cancel_exchange")
    def cancel_exchange(exchange_id: str, reason: str = "",
                        attempt: int = 1) -> str:
        """Cancel an exchange, releasing held stock. A later attempt may
        start fresh with a higher attempt number."""
        key = _key(ctx, "cancel", attempt)
        try:
            res = _ops.cancel_exchange(db, case_id=case_id, run_id=run_id,
                                       op_key=key, exchange_id=exchange_id,
                                       reason=reason)
        except (_ops.TransientError,) as exc:
            return _err(str(exc), retry_same_key=True, op_key=key)
        except _ops.OperationError as exc:
            return _err(str(exc), op_key=key)
        return _ok(exchange_id=res.exchange_id, status=res.status,
                   hold_released=res.hold_released,
                   duplicate=res.duplicate, op_key=key)

    @tool
    @neatlogs.span(kind="TOOL", tool_name="record_denial")
    def record_denial(reason: str) -> str:
        """Record a policy denial. Writes no fulfillment rows. The reason
        must quote the observed fact and cannot be empty."""
        try:
            _ops.note_case(db, case_id=case_id, state="denied",
                           detail=reason)
        except _ops.OperationError as exc:
            return _err(str(exc))
        return _ok(state="denied")

    @tool
    @neatlogs.span(kind="TOOL", tool_name="record_clarification")
    def record_clarification(question: str) -> str:
        """Record what is needed from the customer. Writes no rows. The
        question must state what is missing and cannot be empty."""
        try:
            _ops.note_case(db, case_id=case_id, state="needs_information",
                           detail=question)
        except _ops.OperationError as exc:
            return _err(str(exc))
        return _ok(state="needs_information")

    @tool
    @neatlogs.span(kind="TOOL", tool_name="escalate_without_exchange")
    def escalate_without_exchange(reason: str, attempt: int = 1) -> str:
        """Escalate when no exchange was started (no stock to release).
        For partial state with a held unit, use escalate_to_human."""
        key = _key(ctx, "escalate", attempt)
        try:
            res = _ops.record_escalation(db, case_id=case_id, run_id=run_id,
                                         op_key=key, reason=reason)
        except (_ops.TransientError,) as exc:
            return _err(str(exc), retry_same_key=True, op_key=key)
        except _ops.OperationError as exc:
            return _err(str(exc), op_key=key)
        return _ok(exchange_id=res.exchange_id, status=res.status,
                   duplicate=res.duplicate, op_key=key)

    return [get_order, get_return_policy, find_exchange_stock,
            get_active_exchange, get_operation_status, verify_exchange,
            reserve_replacement, create_return, create_label,
            finalize_arranged, escalate_to_human, cancel_exchange,
            record_denial, record_clarification, escalate_without_exchange]

